<?php

namespace Tests\Unit;

use Tests\TestCase;
use Illuminate\Foundation\Testing\DatabaseMigrations;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use App\Domain\Patrimonial\Ouvidoria\Services\ProcessoEletronicoService;

class ValidateAnexoBase64eAdicionaCaminhoTemporarioTest extends TestCase
{
    /**
     * @throws \Exception
     */
    public function testValidateAnexoBase64eAdicionaCaminhoTemporario()
    {
        $anexo = [
            "nome" => "test",
            "conteudo" => "data:image/jpeg;base64,",
            "type" => "image/jpeg"
        ];
        ProcessoEletronicoService::validaAnexoBase64eAdicionaCaminhoTemporario($anexo);
        $this->assertArrayHasKey('caminho', $anexo);
        $this->assertFileExists($anexo['caminho']);
        $this->assertFileIsReadable($anexo['caminho']);
    }
}
